 const barrage=Array.from({length:128},()=>{const head=mesh(new THREE.ConeGeometry(.027,.14,6),0xffdf9d);root.add(head);const trail=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3()]),new THREE.LineBasicMaterial({color:0x80d9ff,transparent:true,opacity:.75}));root.add(trail);return {head,trail};});
 const sun=new THREE.Group();root.add(sun);const sunSphere=new THREE.Mesh(new THREE.SphereGeometry(2.7,48,32),new THREE.ShaderMaterial({uniforms:{clock:{value:0}},vertexShader:'varying vec3 p;void main(){p=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'uniform float clock;varying vec3 p;float hash(vec3 a){return fract(sin(dot(a,vec3(127.1,311.7,74.7)))*43758.5453);}float noise(vec3 a){vec3 i=floor(a),f=fract(a);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}float fbm(vec3 a){float v=0.,w=.5;for(int i=0;i<5;i++){v+=noise(a)*w;a=a*2.03+vec3(3.1,1.7,2.4);w*=.5;}return v;}void main(){vec3 q=normalize(p);float cells=fbm(q*7.+vec3(clock*.04,0,clock*.025));float fire=smoothstep(.15,.82,cells);vec3 c=mix(vec3(.9,.18,.015),vec3(1.,.94,.55),fire);float filaments=pow(1.-abs(fbm(q*15.+cells)-.5)*2.,9.);gl_FragColor=vec4(c+filaments*vec3(.18,.12,.015),1.);}'}));sun.add(sunSphere);const corona=glow(0xffb83d,8);sun.add(corona);const solarBeam=line(0xffd36e,.08);
