 const centerMarkers=Array.from({length:15},(_,i)=>{const g=new THREE.Group();g.add(mesh(new THREE.CylinderGeometry(.023,.035,.09,6),0xf4de8e));const ring=new THREE.Mesh(new THREE.TorusGeometry(.055,.004,5,24),new THREE.MeshBasicMaterial({color:0xf4d682}));ring.rotation.x=Math.PI/2;g.add(ring);root.add(g);return g;});
 const banner=document.createElement('div');banner.className='technology-banner';banner.hidden=true;document.querySelector('.world').append(banner);
 function clear(){banner.hidden=true;root.visible=false;layers.forEach(l=>l.clear());layerHits.fill(-Infinity);}
